<?= $this->extend('layouts/main') ?><?= $this->section('content') ?><div class="form-wrap"><h1><?= $pedido ? 'Editar pedido' : 'Nuevo pedido' ?></h1><form method="post" action="<?= site_url($pedido ? 'admin/pedidos/actualizar/'.$pedido['idPedido'] : 'admin/pedidos/guardar') ?>"><?= csrf_field() ?><label>ID usuario</label><input type="number" name="idUsuario" value="<?= esc($pedido['idUsuario'] ?? session()->get('idUsuario')) ?>" required><label>Total</label><input type="number" step="0.01" name="TotalComprar" value="<?= esc($pedido['TotalComprar'] ?? 0) ?>" min="0" required><?php if($pedido): ?><label>Estado</label><select name="estado"><option <?= ($pedido['estado'] ?? '') === 'Pendiente' ? 'selected' : '' ?>>Pendiente</option><option <?= ($pedido['estado'] ?? '') === 'En camino' ? 'selected' : '' ?>>En camino</option><option <?= ($pedido['estado'] ?? '') === 'Entregado' ? 'selected' : '' ?>>Entregado</option></select><?php endif; ?><button class="button">Guardar pedido</button></form></div><?= $this->endSection() ?>
